+export function resolveMarkdownSourceXrefDestination(
+	target: MarkdownXrefTarget,
+	fallbackUrl: string,
+): string {
+	if (target.path.length === 0) {
+		return target.fragment === undefined ? fallbackUrl : `#${target.fragment}`;
+	}
